import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Home Assistant Card Editor","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas-plugins/homeassistant-card-editor.md","filePath":"en/projects/atlas-plugins/homeassistant-card-editor.md","lastUpdated":1792859421000}'),s={name:"en/projects/atlas-plugins/homeassistant-card-editor.md"};function r(n,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="home-assistant-card-editor" tabindex="-1">Home Assistant Card Editor <a class="header-anchor" href="#home-assistant-card-editor" aria-label="Permalink to &quot;Home Assistant Card Editor&quot;">​</a></h1><p>The Home Assistant Card Editor is the first official ATLAS reference plugin. It shows how plugin lifecycle, discovery, Administration, Hub display, import/export and package building work together.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>As of 2026-10-16: reference plugin <strong>0.2.0-alpha.108</strong> in App <strong>0.1.312</strong>. It updates with ATLAS, not by replacement as an external plugin. See the <a href="./../atlas/card-editor">Editor guide</a> and <a href="./../atlas/frontend">App/Runtime projects</a> for shared projects and complete HACS Card export/import instructions.</p><p>Product decision on 2026-10-13: the editor remains Expert-only. Simple mode and its switch will not return. Supported legacy project imports remain compatible.</p><p>Starting with HA app <strong>0.1.292</strong>, the start-mode selector is also removed from HA app configuration and Administration. Older saved Simple values are treated as Expert; credentials and other settings are preserved.</p><p>The plugin provides an editor for Home Assistant cards. It supports the Expert workflow, entity selection, resource checks, YAML/JSON import, HACS-oriented bundle exports and multilingual card packages. The former visible Simple mode has been removed; the editor now opens directly in the Expert workflow.</p><p>In the Expert workflow, the background grid stays square. The number of columns is controlled by a horizontal slider above the surface, while the number of rows is controlled by a vertical slider on the left. A separate Zoom slider changes only the cell size and scales width and height together. The previous stretch behavior is now split into field count and zoom.</p><h2 id="card-list-on-tablets" tabindex="-1">Card list on tablets <a class="header-anchor" href="#card-list-on-tablets" aria-label="Permalink to &quot;Card list on tablets&quot;">​</a></h2><p>Starting with HA app <strong>0.1.290</strong>, editor widths from 521 to 1180 pixels show two cards side by side in a scrollable window. Its height follows the first card row and is capped on short screens. Scroll to reach the remaining cards. The action buttons above the list also use two equal-width columns. Narrow phones keep one column; the desktop sidebar remains unchanged. The embedded editor width determines the layout, not the device name. Existing projects, favorites and settings are preserved.</p><h2 id="mobile-grid-and-title-controls" tabindex="-1">Mobile grid and title controls <a class="header-anchor" href="#mobile-grid-and-title-controls" aria-label="Permalink to &quot;Mobile grid and title controls&quot;">​</a></h2><p>Starting with HA app <strong>0.1.291</strong>, Grid &amp; zoom is collapsed by default at editor widths up to 1180 pixels. Tap to show the X, Y and zoom sliders; opening or closing the group changes no values or cards. Switching to desktop width shows the sliders directly again.</p><p>On tablets, the title field, Apply title and Use entity name share one row. On narrow phones, the title field sits above the two equal-width buttons. This layout applies in DE/EN/FR.</p><h2 id="live-connection-with-large-entity-catalogs" tabindex="-1">Live connection with large entity catalogs <a class="header-anchor" href="#live-connection-with-large-entity-catalogs" aria-label="Permalink to &quot;Live connection with large entity catalogs&quot;">​</a></h2><p>Starting with HA app <strong>0.1.293</strong>, ATLAS processes entity snapshots and live events in arrival order. An ongoing snapshot can no longer finish after a subsequently received event and overwrite it with older values. Queued messages from a closed connection are ignored; a failed replacement socket reports its own failure status. Saved cards, positions and credentials remain unchanged.</p><h2 id="extension-points" tabindex="-1">Extension Points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension Points&quot;">​</a></h2><p>The editor currently uses these ATLAS extension points:</p><ul><li><code>homeassistant.card-editor</code></li><li><code>homeassistant.card-target</code></li><li><code>homeassistant.entity-picker</code></li><li><code>homeassistant.exporter</code></li><li><code>atlas.plugin.package-builder</code></li></ul><h2 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h2><p><code>createHomeAssistantCardEditorPluginInstallPackage()</code> creates the first install package for this reference plugin. It includes a plugin manifest, a README and an example Home Assistant card configuration.</p><h2 id="hub-description" tabindex="-1">Hub Description <a class="header-anchor" href="#hub-description" aria-label="Permalink to &quot;Hub Description&quot;">​</a></h2><p>Hub and Administration can display localized descriptions from the plugin repository. The selected language prefers <code>descriptions.de</code>, <code>descriptions.en</code> or <code>descriptions.fr</code> when available. English remains the fallback.</p>',22)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
